"use strict";
const test=require("node:test");const assert=require("node:assert/strict");const fs=require("node:fs");const os=require("node:os");const path=require("node:path");
const {compileIntent,verifyCompiledIntent,diffCompiledIntent}=require("../src/engine/intent-engine");
const {createBundle,verifyBundle}=require("../src/public/bundle");
function temp(){return fs.mkdtempSync(path.join(os.tmpdir(),"intent-bundle-"));}
function intent(version=1){return{intent_id:"bundle.intent",version,scope:{id:"bundle.intent",parents:[]},clauses:[{id:"privacy",kind:"invariant",target:"privacy.telemetry",operator:"eq",value:false,severity:"hard",provenance:{type:"human",ref:"REQ-1",statement:"Never add telemetry without explicit approval."}}],edges:[]};}
test("shareable bundles accept Intent artifacts and remove raw human provenance statements",()=>{const root=temp();const before=compileIntent({intent:intent(1)});const after=compileIntent({intent:{...intent(2),clauses:[{...intent(2).clauses[0],confidence:.9}]}});const verification=verifyCompiledIntent({intent:after,facts:{"privacy.telemetry":false}});const delta=diffCompiledIntent({before,after});const files=[];for(const [name,value] of [["contract",after],["delta",delta],["verification",verification]]){const file=path.join(root,`${name}.json`);fs.writeFileSync(file,JSON.stringify(value));files.push(file);}const bundleDir=path.join(root,"bundle");const manifest=createBundle({artifactFiles:files,outputDir:bundleDir,privacyProfile:"shareable"});assert.equal(manifest.source_artifacts.length,3);assert.equal(verifyBundle(bundleDir).status,"verified");const serialized=fs.readdirSync(path.join(bundleDir,"artifacts")).map(name=>fs.readFileSync(path.join(bundleDir,"artifacts",name),"utf8")).join("\n");assert.equal(serialized.includes("Never add telemetry"),false);assert.equal(serialized.includes('"ref": "REQ-1"'),true);});
test("tampered Intent artifacts are rejected before bundle creation",()=>{const root=temp();const artifact=JSON.parse(JSON.stringify(compileIntent({intent:intent()})));artifact.clauses[0].confidence=.1;const file=path.join(root,"tampered.json");fs.writeFileSync(file,JSON.stringify(artifact));assert.throws(()=>createBundle({artifactFiles:[file],outputDir:path.join(root,"bundle")}),/Intent artifact fingerprint mismatch/);});
